SELECT COUNSEL_ID, TITLE, WRITER, STATUS, REGIST_DT FROM COUNSEL
AND (TITLE LIKE '%' || #{searchKeyword} || '%' OR WRITER LIKE '%' || #{searchKeyword} || '%')
ORDER BY REGIST_DT DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*)
FROM COUNSEL
WHERE COUNSEL_ID = #{counselId}
	AND PASSWORD = #{password}

SELECT COUNSEL_ID, TITLE, WRITER, STATUS, REGIST_DT FROM COUNSEL
AND WRITER LIKE '%' || #{searchKeyword} || '%'
AND STATUS = #{status}
ORDER BY REGIST_DT DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*) FROM COUNSEL
AND WRITER LIKE '%' || #{searchKeyword} || '%'
AND STATUS = #{status}
